MultiLanguageSpellData['it'][223844] = {name = "Progetto di Archeologia", additional_info = "Istantaneo\n[q]Questo dispositivo portatile era usato dagli auguri delle stelle per concentrare un'immensa quantità di luce stellare in una zona molto piccola. Il dispositivo era usato principalmente durante i festival, nei rituali di adorazione delle stelle o quando un augure aveva bisogno di qualcosa su uno scaffale in alto."}
MultiLanguageSpellData['it'][223845] = {name = "Ramo dell'Arcan'dor", additional_info = "Portata di 100 m\nIstantaneo\n[q]1 Avvizziti ammaliati.\n\n Consegnarli a Shal'aran o cliccare col pulsante destro per liberarli.\n\n Allontanarsi da Suramar dissolve l'effetto."}
MultiLanguageSpellData['it'][223846] = {name = "Progetto di Archeologia", additional_info = "Istantaneo\n[q]Principi e principesse regnanti a Suramar indossavano le loro corone soltanto durante gli eventi più formali. Per il resto del tempo erano lasciate da parte, perché considerate poco eleganti."}
MultiLanguageSpellData['it'][223847] = {name = "Avvizzito Ammaliato Avanzato", additional_info = nil}
MultiLanguageSpellData['it'][223848] = {name = "Progetto di Archeologia", additional_info = "Istantaneo\n[q]Il Forte Corvonero era mantenuto da una piccola schiera di servi. Uno di questi si chiamava Kalyndras, ed era responsabile della supervisione dell'armeria e del deposito munizioni. Come la maggior parte dei servi di Crinocorvo, cadde per mano dei demoni durante la Guerra degli Antichi."}
MultiLanguageSpellData['it'][223849] = {name = "Progetto di Archeologia", additional_info = "Istantaneo\n[q]Questo potentissimo Focus Magico degli Alti Nobili è stato distrutto durante una spedizione archeologica. Tutto ciò che rimane di quest'oggetto sono delle schegge."}
MultiLanguageSpellData['it'][223850] = {name = "Progetto di Archeologia", additional_info = "Istantaneo\n[q]Questa chiave non apre alcuna porta. È sostanzialmente un segno di benvenuto all'Accademia, un modo per dire: \"Le nostre porte sono aperte\"."}
MultiLanguageSpellData['it'][223851] = {name = "Progetto di Archeologia", additional_info = "Istantaneo\n[q]Venerato dai minatori e dai fabbri, Corno Ferreo è stato uno dei primi Tauren a stabilire la sua dimora sulle Isole Disperse. I suoi discendenti hanno continuato la sua tradizione della lavorazione del metallo all'Enclave dei Corno Ferreo, situata vicino alla sommità di Alto Monte."}
MultiLanguageSpellData['it'][223852] = {name = "Progetto di Archeologia", additional_info = "Istantaneo\n[q]I Drogbar sono sempre stati dei maestri nell'arte dell'oreficeria. In particolare, gli Sciamani tribali indossavano delle pesanti collane formate da tre pietre. Queste collane venivano tramandate dai maestri agli studenti."}
MultiLanguageSpellData['it'][223853] = {name = "Progetto di Archeologia", additional_info = "Istantaneo\n[q]Eche'ro era mascotte, cavalcatura nonché fedele alleato di Huln Alto Monte, eroe leggendario della Guerra degli Antichi."}
MultiLanguageSpellData['it'][223854] = {name = "Progetto di Archeologia", additional_info = "Istantaneo\n[q]L'occhio di un potente demone, preservato nelle fredde e rocciose terre di Stromheim. Degli scritti risalenti alla Guerra degli Antichi indicano che Undravius era un vilsignore comandante che voleva estirpare ogni forma di vita da Azeroth."}
MultiLanguageSpellData['it'][223855] = {name = "Progetto di Archeologia", additional_info = "Istantaneo\n[q]Sotto la guida dei riluttanti Ingegneri Mo'arg, i Cacciatori di Demoni sono riusciti a creare molti di questi portali verso Mardum. Sfortunatamente, non hanno mai funzionato a dovere, lasciando i demoni più spesso fuori che dentro."}
MultiLanguageSpellData['it'][223856] = {name = "Progetto di Archeologia", additional_info = "Istantaneo\n[q]Molti incauti avventurieri sono andati incontro alla morte attivando uno di questi dispositivi senza conoscerne il funzionamento. Non si sa mai se attivandolo si finisca per evocare un solo Imp o una legione di Signori delle Fosse."}
MultiLanguageSpellData['it'][223857] = {name = "Progetto di Archeologia", additional_info = "Istantaneo\n[q]Non è chiaro il motivo per il quale degli esseri viventi, sia demoniaci che azerotiani, decidano di inimicarsi Mannoroth tenendo un po' del suo sangue all'interno di un vasetto."}
MultiLanguageSpellData['it'][223858] = {name = "Progetto di Archeologia", additional_info = "Istantaneo\n[q]Nella loro fuga da Argus, pochi furono i manufatti che i Draenei portarono con loro. Questo libro è una delle poche reliquie oggi ancora integre."}
