MultiLanguageSpellData['it'][223892] = {name = "Cambio Alleanza", additional_info = "Portata di 40 m\n{Canalizzato (10 s di lancio} {) 10 s di recupero}\n[q]Trasferisce dei Sussurri Oscuri nella mente di un alleato dopo 10 s.\n\n Lanciare quest'abilità ti rende alleato della Legione per 15 s.\n\n Dissolve 1 accumulo di Mente Fragile."}
MultiLanguageSpellData['it'][223894] = {name = "Isteria", additional_info = "Portata di 50 m\n{2 s di lancio} {1 min di recupero}\n[q]Provoca un'isteria di massa in un gruppo di bersagli, inducendoli a combattere contro i propri alleati per 10 s.\n\n Lanciare quest'abilità ti rende alleato della Legione per 15 s.\n\n L'effetto non può verificarsi su bersagli che l'abbiano già subito di recente."}
