MultiLanguageSpellData['it'][225127] = {name = "Spazzata Arcana", additional_info = "Spazzata Arcana Livello 80\n[q0][Item Effect]1 s di recupero\nCirca 5 apparenze ogni minuto\n[q]Gli attacchi in mischia hanno una probabilità di colpire tutti i nemici frontali, infliggendo 324 danni da arcano."}
MultiLanguageSpellData['it'][225128] = {name = "Tranquillità del Pozzo Oscuro", additional_info = "Tranquillità del Pozzo Oscuro Livello 80\n[q0][Item Effect]Circa 3 apparenze ogni minuto\n[q]Gli incantesimi di cura hanno una probabilità di fornire al bersaglio Tranquillità del Pozzo Oscuro, rigenerandone 1342 salute in 12 s. Curare un alleato con questo effetto attivo lo fa esplodere, curando gli alleati vicini di 224 ."}
MultiLanguageSpellData['it'][225129] = {name = "Triumvirato", additional_info = "[q0][Item Effect]Circa 0.7 apparenze ogni minuto\n[q]Gli attacchi in mischia e a distanza hanno una probabilità di fornirti un incantamento di fuoco, di gelo o arcano per 20 s."}
