MultiLanguageSpellData['it'][239647] = {name = "Cacciatore Epico", additional_info = "Istantaneo\n[q]Completare la costruzione del Disgregatore Fatuo fornisce l'accesso a:\n\nBoss esterni\n L'energia del Disgregatore Fatuo attira alla Riva Dispersa i nemici più potenti.\n\nPortali Fatui Instabili\n L'attivazione del Disgregatore Fatuo provoca l'apertura alla Riva Dispersa di portali capaci di evocare terribili creature.\n\nEncomi dell'Artigiano d'Armature\n Artigiani sopraffini ricevono degli encomi per i loro sforzi, con i quali possono creare i più leggendari degli oggetti."}
MultiLanguageSpellData['it'][239648] = {name = "Forze dell'Ordine", additional_info = "Istantaneo\n[q]Completare la costruzione del Centro di Comando fornisce l'accesso a:\n\nMissioni mondiali della Cattedrale\n Con il centro finito, gli sforzi possono concentrarsi sull'assalto alla Cattedrale della Notte Eterna.\n\nRinforzi degli Spezzalegione\n I comandanti degli Spezzalegione ricevono supporti aggiuntivi sulle Isole Disperse.\n\nAssalti Élite\n Valorosi campioni affrontano impegnative ma lucrative missioni nel cuore della Riva Dispersa."}
