MultiLanguageSpellData['it'][254410] = {name = "Raffica di Vento", additional_info = "Portata di 30 m\n{Istantaneo} {12 s di recupero}\n[q]Deconcentra il bersaglio con un soffio di vento, interrompendo il lancio d'incantesimi e impedendo il lancio di altri incantesimi della stessa scuola di magia per 3 s."}
MultiLanguageSpellData['it'][254411] = {name = "Epurazione", additional_info = "{4% della base mana} {Portata di 30 m}\nIstantaneo\n[q]Epura il bersaglio nemico, dissolvendo 1 effetto benefico.[Epurare con successo un bersaglio fornisce una carica di Arma del Maelstrom.]"}
MultiLanguageSpellData['it'][254412] = {name = "Maleficio", additional_info = "Portata di 30 m\n{1.7 s di lancio} {35 s di recupero}\n[q]Trasforma il nemico in una rana per 1 min. In questo stato, il bersaglio è inabilitato e non può attaccare o lanciare incantesimi. Eventuali danni potrebbero annullare l'effetto. L'effetto può essere attivo su un solo bersaglio alla volta. Funziona solo su umanoidi e bestie."}
MultiLanguageSpellData['it'][254413] = {name = "Totem della Marea Curativa", additional_info = "1.12% della base mana\n{Istantaneo} {3 min di recupero}\n[q]Evoca per 10 s ai tuoi piedi un totem che pulsa ogni 2 s, curando di ([350% of Spell Power]) tutti i membri del gruppo o dell'incursione entro 40 m."}
MultiLanguageSpellData['it'][254414] = {name = "Lupo Spettrale", additional_info = "Istantaneo\n[q]Ti permette di assumere la Forma di Lupo Spettrale, aumentando la velocità di movimento del 30% e impedendo che la velocità di movimento venga ridotta a meno del 100%."}
MultiLanguageSpellData['it'][254415] = {name = "Totem del Vincolo Terrestre", additional_info = "Portata di 35 m\n{Istantaneo} {30 s di recupero}\n[q]Evoca per 20 s sulla posizione bersaglio un Totem della Terra con (2 * [Total Health] / 100) salute, che riduce la velocità di movimento dei nemici entro 10 m."}
MultiLanguageSpellData['it'][254416] = {name = "Totem dell'Adescamento Magico", additional_info = "1.18% della base mana\n{Istantaneo} {30 s di recupero}\n[q]Evoca ai piedi dell'incantatore un Totem dell'Aria con 5 salute, che reindirizza verso il totem stesso tutti gli incantesimi d'attacco lanciati contro un vicino membro del gruppo o dell'incursione. Non influenza incantesimi ad area d'effetto. Dura 3 s."}
MultiLanguageSpellData['it'][254417] = {name = "Scudo di Terra", additional_info = "{3% della base mana} {Portata di 40 m}\n{Istantaneo} {6 s di recupero}\n[q]Protegge il bersaglio con uno scudo di terra, riducendone tutti i danni subiti del 15% e curandolo di ([112.5% of Spell Power]) quando subisce danni pari al 4% della sua salute massima. 4 cariche.\n\n Scudo di Terra può essere utilizzato solo su un bersaglio alla volta.\n(1s di recupero)"}
MultiLanguageSpellData['it'][254418] = {name = "Eruzione Benefica", additional_info = "{4% della base mana} {Portata di 40 m}\n1.5 s di lancio\n[q]Un'eruzione curativa rapida, che cura un bersaglio alleato di 10."}
MultiLanguageSpellData['it'][254419] = {name = "Marea Benefica", additional_info = "{1.6% della base mana} {Portata di 40 m}\n{Istantaneo} {6 s di recupero}\n[q]Acque curative bagnano un bersaglio alleato, curandolo di 5 e di 10 aggiuntivi in 15 s."}
MultiLanguageSpellData['it'][254420] = {name = "Purificazione Spirituale", additional_info = "{2.6% della base mana} {Portata di 40 m}\n{Istantaneo} {8 s di recupero}\n[q]Dissolve tutte le maledizioni e gli effetti magici da un bersaglio amico."}
MultiLanguageSpellData['it'][254421] = {name = "Ondata di Cura", additional_info = "{1.8% della base mana} {Portata di 40 m}\n2.5 s di lancio\n[q]Un'ondata curativa efficace, che cura un bersaglio alleato di 20."}
MultiLanguageSpellData['it'][254422] = {name = "Totem del Flusso Vitale", additional_info = "2.2% della base mana\n{Istantaneo} {30 s di recupero}\n[q]Evoca per 15 s ai tuoi piedi un totem che cura [ Flusso Impetuoso : due membri del gruppo o dell'incursione feriti / un membro del gruppo o dell'incursione ferito] entro 40 m di ([67.68% of Spell Power]) ogni 2 s."}
MultiLanguageSpellData['it'][254423] = {name = "Catena di Guarigione", additional_info = "{5% della base mana} {Portata di 40 m}\n2.5 s di lancio\n[q]Cura il bersaglio amico di 5, poi cura i bersagli del gruppo o dell'incursione più feriti vicini. Le cure si riducono del 30 % a ogni bersaglio successivo. Cura fino a un massimo di 4 bersagli."}
