MultiLanguageSpellData['it'][257671] = {name = "Ira Tonante di Golganneth", additional_info = "[q0][Item Effect]Portata di 100 m\nIstantaneo\n[q]Le abilità d'attacco hanno una probabilità di creare una Tempesta Devastante sulla posizione del bersaglio, infliggendo ( 172 * 6) danni da natura suddivisi tra tutti i nemici entro 6 m in 6 s.\n\nIra Tonante di Golganneth\n Il potenziamento del Pantheon fa sì che gli attacchi automatici provochino un'esplosione di fulmini, infliggendo [ 1 * ([Mainhand weapon min base speed]) * 96 ] danni da natura a tutti i nemici entro 8 m dal bersaglio. Dura 15 s."}
MultiLanguageSpellData['it'][257673] = {name = "Energia Vitale", additional_info = "Istantaneo\n[q]L'Energia Vitale di Eonar aumenta man mano che le forze d'invasione della Legione vengono sconfitte. Quando raggiunge 100 Energia Vitale, Eonar attacca la Paraxis e le forze della Legione con Forza Vitale.\n\n\nForza Vitale Portata infinita 3 s di lancio Eonar raccoglie la propria forza vitale e fa esplodere la Paraxis, infliggendo danni da natura. Inoltre, un'ondata di energia spazza la zona, danneggiando tutti gli invasori nemici."}
MultiLanguageSpellData['it'][257674] = {name = "Furtività", additional_info = "{Istantaneo} {2 s di recupero}\n[q]Attiva la modalità furtiva, che ti permette di seguire i nemici senza essere visto.\n\n La modalità furtiva rigenera 2 salute ogni 1 s."}
MultiLanguageSpellData['it'][257676] = {name = "Ricostruzione", additional_info = "2.5 s di lancio\n[q]L'incantatore attira a sé rocce e detriti per riempire le crepe nella propria forma, rigenerando il 4% della propria salute massima ogni 1 s per 10 s."}
