MultiLanguageSpellData['it'][257715] = {name = "Segaossa Cerimoniale", additional_info = "2 s di lancio\n[q]I Drust utilizzano gli organi interni di svariati animali nei loro rituali. I segaossa sono fondamentali per aprire un varco attraverso le costole delle bestie più grandi ed estrarne il cuore."}
MultiLanguageSpellData['it'][257716] = {name = "Tomo Antico Runico", additional_info = "2 s di lancio\n[q]I Drust più forti generalmente custodivano questi tomi per preservarne gli incantamenti magici e per utilizzarli come condotti per la raccolta d'energia. Gli studiosi che hanno provato a tradurre l'antica lingua utilizzata in questi tomi, hanno tutti perso il senno man mano che aumentava la loro comprensione dei contenuti in essi trascritti."}
MultiLanguageSpellData['it'][257717] = {name = "Falce Sbudellante", additional_info = "2 s di lancio\n[q]Si è scoperto che i Drust utilizzavano molti strumenti diversi nei loro rituali. Uno di questi è una falce, utilizzata per aprire la pancia dei loro sacrifici ed estrarne le interiora, che venivano poi usate dai Drust per i loro oscuri scopi."}
MultiLanguageSpellData['it'][257718] = {name = "Lama Seghettata dei Drust", additional_info = "2 s di lancio\n[q]Utilizzate nei combattimenti e in antiche cerimonie, le lame dei Drust sono oggetti davvero terrificanti. Quando viene impugnata da un membro di questa razza, la lama può facilmente raggiungere gli organi vitali in un batter d'occhio."}
MultiLanguageSpellData['it'][257719] = {name = "Feticcio Rituale", additional_info = "2 s di lancio\n[q]Quando i Drust stavano apprendendo come vincolare le anime ai costrutti, utilizzavano le ossa dei loro morti come ricettacoli. Una volta che il rituale era completato, i terribili feticci emettevano un'inquietante luminescenza bluastra, presumibilmente una manifestazione del potere dell'anima racchiusa."}
MultiLanguageSpellData['it'][257720] = {name = "Vaso di Akun'jar", additional_info = "2 s di lancio\n[q]Gli Zandalari adorano numerose divinità spirituali che chiamano Loa. Una di esse è il grande sauro del tuono, Akunda, il Loa delle Tempeste e dei nuovi inizi. Il suo credo è che la tempesta abbia il potere di spazzar via il rammarico e la tristezza."}
MultiLanguageSpellData['it'][257721] = {name = "Urna del Passaggio", additional_info = "2 s di lancio\n[q]Durante l'era finale del Concilio delle Tribù, si diffuse una piaga del sangue che uccise migliaia di Troll. Si decise che i corpi, troppo infetti per un'appropriata sepoltura, venissero bruciati e tenuti in urne speciali. Col tempo, questo divenne un metodo alquanto comune di sepoltura tra gli Zandalari."}
MultiLanguageSpellData['it'][257722] = {name = "Idolo di Rezan", additional_info = "2 s di lancio\n[q]Nelle ere, molti Re hanno governato l'Impero degli Zandalari. Tutti avevano ben chiara la loro posizione nei confronti di Rezan, il più grande dei Loa, e lo ricordavano sempre nelle loro preghiere. Questo Loa onora le gesta più delle parole, ma prende molto sul serio gli sgarri ed è noto per portare rancore."}
MultiLanguageSpellData['it'][257723] = {name = "Cappuccio del Gran Speziale", additional_info = "2 s di lancio\n[q]I praticanti di alchimia Zandalari hanno fondato un'organizzazione ermetica all'interno dell'Impero, nota come \"Shadra'zan\". Per accedere a questa gilda, è necessario portare a termine un rituale in cui la recluta deve creare una pozione con il proprio stesso sangue: se sopravvive ai suoi effetti, viene considerato degno di apprendere i segreti del gruppo."}
MultiLanguageSpellData['it'][257724] = {name = "Maschera Vudù di Bwonsamdi", additional_info = "2 s di lancio\n[q]Per onorare il Loa della Morte, gli Zandalari indossano queste maschere nei loro rituali di preghiera. Bwonsamdi può rispondere con gentilezza o far loro provare indicibili dolori, a seconda del suo umore. Egli è il protettore dei morti e porta gli spiriti di tutti coloro che lo onorano nel suo reame, l'Aldilà."}
MultiLanguageSpellData['it'][257730] = {name = "Benedizione dell'Invocatore Celeste", additional_info = "30 s di lancio\n[q]Potenzia i Sethrak vicini con il potere della tempesta."}
