MultiLanguageSpellData['it'][273845] = {name = "Catena di Fulmini", additional_info = "Portata di 30 m\n{2 s di lancio} {6 s di recupero}\n[q]Colpisce un nemico con un fulmine che danneggia un altro nemico vicino. L'incantesimo colpisce fino a un massimo di 3 bersagli, infliggendo danni da natura minori a ogni bersaglio successivo."}
MultiLanguageSpellData['it'][273846] = {name = "Totem del Flusso Vitale", additional_info = "40 mana\nIstantaneo\n[q]Evoca per 1 min ai piedi dell'incantatore un Totem del Flusso Vitale con 5 salute, che cura gli alleati vicini di 0 ogni 2 s."}
MultiLanguageSpellData['it'][273847] = {name = "Flusso Vitale", additional_info = "Istantaneo\n[q]Evoca ai tuoi piedi per 15 s un totem che cura [ Flusso Impetuoso : due membri feriti del gruppo o dell'incursione / un membro ferito del gruppo o dell'incursione] entro 40 m di ([67.68% of Spell Power]) ogni 2 s.\n\n Se si conosce già [ Totem del Nubifragio : Totem del Nubifragio / Totem del Flusso Vitale ], le cariche di [ Totem del Nubifragio : Totem del Nubifragio / Totem del Flusso Vitale ] aumentano di 1."}
