MultiLanguageSpellData['it'][273851] = {name = "Scrigno dell'Anima", additional_info = "2 s di lancio\n[q]Quando un'anima viene chiamata nell'aldilà, è libera di vagare per il mondo materiale se non viene vincolata al momento dell'arrivo. I Drust hanno creato speciali prigioni per poterle successivamente usare nei loro oscuri rituali, il cui scopo è far soffrire l'anima a Thros e trasformarla in una versione distorta di ciò che era."}
MultiLanguageSpellData['it'][273852] = {name = "[q3]Danza dei Morti", additional_info = "2 s di lancio\n[q]Quando i Drust desideravano incantare le menti di un nemico o di una preda, spesso lo facevano con metodi sottili, lasciando piccoli emblemi nei paraggi del proprio bersaglio. Questi oggetti curiosi, se ricevevano sufficiente attenzione, evocavano la visione di uno spettro danzante. Questo spetto ipnotizzava tutti coloro che lo guardavano, rendendo i bersagli docili e facili da eliminare.\n[q3]Danza dei Morti\nSi vincola alla raccolta\nGiocattolo\n[q2]Usa: Evochi una strega danzante spettrale. (10 Min Recupero)"}
MultiLanguageSpellData['it'][273853] = {name = "Tempesta di Sabbia", additional_info = "Tempesta di Sabbia Livello 80\n[q]Gli incantesimi e le abilità hanno una probabilità di evocare un ciclone di venti violenti. I nemici all'interno del ciclone subiscono 68 danni ogni 2 s e ti infliggono danni ridotti di 228 ."}
MultiLanguageSpellData['it'][273854] = {name = "[q3]Spettro Ripristinato", additional_info = "2 s di lancio\n[q]Man mano che i Drust prendevano confidenza su come intrappolare le anime all'interno degli oggetti, divennero più abili nel creare i costrutti di morte da usare come ricettacoli. Gli Spettri sono tra le creature più terrificanti di questo genere: senza alcuna memoria e composti da membra che non possono più decomporsi, questi esseri non si stancano mai e sono pronti a inseguire la loro preda per tutta l'eternità.\n[q3]Pila d'Ossa\nSi vincola alla raccolta\n[q2]Usa: Ti insegna a evocare uno Spettro Ripristinato.\n[q2]Clicca col pulsante destro per evocare e congedare uno Spettro Ripristinato.\nRichiede dal livello 1 al 80 ( 80)"}
MultiLanguageSpellData['it'][273855] = {name = "[q3]Feticcio della Mente Tormentata", additional_info = "2 s di lancio\n[q]Questi feticci erano elementi fondamentali per distorcere la mente degli avversari, facendo germogliare le loro insicurezze e soffocando ogni pensiero positivo. Coloro che ne subivano l'influenza, cominciavano a dubitare delle proprie motivazioni, delle proprie idee o del proprio coraggio e spesso si trovano dalla parte sbagliata di una lama Drust prima di ritrovare la giusta determinazione.\n[q3]Feticcio della Mente Tormentata\n[q7]Si vincola alla Brigata\nUnico equipaggiabileMonile\n+6 Tempra\n[q2]Usa: Riduce la velocità d'attacco e di lancio d'incantesimi del bersaglio nemico attuale del 15% per 5 s. (1 Min, 30 S Recupero)\n45"}
